    Db db; LinearLayout root,body,header; String page="Hoy"; long patient=0; int blue=Color.rgb(5,116,187),pink=Color.rgb(231,61,138),ink=Color.rgb(31,56,79),muted=Color.rgb(103,123,141),bg=Color.rgb(238,247,253);
