    TextView btn(String s,int color,Runnable f){TextView t=txt(s,15,Color.WHITE,true);t.setGravity(Gravity.CENTER);pad(t,12,14);t.setBackground(shape(color,12));t.setOnClickListener(v->f.run());return t;}
